import std.fs

test "mocked read" {
    mock fs.readFile(path: String) -> Result<String, fs.FsError> effect io {
        return Ok("stub")
    }
    match fs.readFile("/etc/hostname") {
        Ok(c) => { assert(c == "stub", "mocked") }
        Err(_) => { assert(false, "mocked") }
    }
}

test "restored" {
    match fs.readFile("/no/such/file") {
        Ok(_) => { assert(false, "restored") }
        Err(_) => { assert(true, "restored") }
    }
}
